INSERT INTO "credibility_assessment" VALUES('cred-2b6a58ff0b53','l3_claim','sc-5143c8a8edfd','high','TRAE 官方文档对自身产品的功能与模型阵容作一手陈述，可证伪、细节具体（具名模型、模式划分、配置项、平台限制）；「上下文窗口未公开」是对文档内容的直接观察而非传闻。','{"independence": "第一方官方文档，权威描述自身产品行为", "quality_density": "高：具名模型清单 + 明确的配置项与平台限制（桌面端/本地专属）", "recency": "现行产品文档，截至抓取时有效"}','一手来源自述其产品；「上下文窗口未公开」属观察性结论，由文档缺失直接支撑。',0,NULL,'active',NULL,'2026-07-06 13:22:22');
INSERT INTO "credibility_assessment" VALUES('cred-2bd027f08737','l3_claim','sc-9e1192eb5de0','high','TRAE 官方文档作为一手来源，对其产品上下文压缩机制的描述具权威性与高信息密度、可证伪；末尾『可能不暴露原生窗口』为研究者推断而非文档陈述，已标注待印证。','{"independence": "厂商官方文档，单一一手来源；对自家产品机制描述具权威性，但非多源独立印证", "quality_density": "描述具体机制（触发条件/行为/适用范围/UI 反馈），信息密度高、可证伪", "recency": "现行官方文档，信息时效有效"}','厂商自文档，对产品行为事实权威；但仅单一来源，关于上下文上限是否等于模型原生窗口的推断需其它来源佐证。',0,NULL,'active',NULL,'2026-07-06 13:22:22');
INSERT INTO "credibility_assessment" VALUES('cred-89b3b04dd915','l3_claim','sc-ecf96379cac9','medium','含一手实测计时数据(21min vs 6min,可证伪、高密度)且时效新鲜(约3周前),但系单来源,核心benchmark(1M上下文、接近Claude)源自智谱官方发布未独立复测。','{"independence": "单一来源(头条号''观察者'');发布事实与benchmark数字追溯至智谱官方公告,仅计时机比为作者一手;无第二独立来源印证。", "quality_density": "高:具体可证伪数字(1M/400-500K上下文、21分钟vs6分钟、10万行代码、MIT协议、2026-06-13发布日),非空泛口号。", "recency": "2026-06-13发布,距今约3周,快变主题(AI模型)下仍有效;API''下周上线''为预测性陈述需后续校验。"}','非纯回音室——作者提供了一手实测计时对比作为增量;但官方能力声明(1M可用、幻觉极低、接近Claude)无独立交叉验证,需在aggregate阶段与其它实测来源印证后方可升为high。',0,NULL,'active',NULL,'2026-07-06 13:22:22');
INSERT INTO "credibility_assessment" VALUES('cred-0426b3a47303','l2_finding','sf-772e6e8b7b75','high','三个互相独立厂商（腾讯/字节/阿里）在各自独立来源中均采用细粒度计量计费并给出具体积分或Token数字，独立性强、密度高、非转发回音室。','{"independence": "3个独立厂商×3条独立来源（src-909ce9fa7145 / src-fc7ca176df63 / src-815dbcf6d1a6）", "quality_density": "含4000积分/月、$20 per 2000 Credits、模型系数0.18–0.30等可证伪数字", "recency": "均为2026年2–7月事件"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:25:55');
INSERT INTO "credibility_assessment" VALUES('cred-34b0e73b8d68','l2_finding','sf-9fce7ed22c62','medium','成本倒逼逻辑在Trae来源中被系统论证，并由Qoder独立的涨价动作印证（2个独立来源指向同一驱动）；但主体为单一来源的分析推理，故定为medium而非high。','{"independence": "Trae分析（src-fc7ca176df63）+ Qoder调价（src-815dbcf6d1a6）=2源独立支撑", "quality_density": "含上下文8k→1M、Agent 10+调用、模型成本差5–10倍、涨价约25%等具体机制与数字", "recency": "2026年"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:25:55');
INSERT INTO "credibility_assessment" VALUES('cred-2e9bf1a01627','l2_finding','sf-2ac03c447dfa','medium','单一来源的产品身份描述，但团队归属、能力清单与定位均具体且为可公开核验的产品事实。','{"independence": "单源（src-909ce9fa7145）", "quality_density": "团队归属+5类能力+定位表述具体", "recency": "2026年当前在售产品"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:25:55');
INSERT INTO "credibility_assessment" VALUES('cred-d14dee30a8e5','l2_finding','sf-d5cf1542c8ae','medium','单一来源描述Trae产品线结构与国内外计费分化，发布日期、目标用户、模型清单与Fast Pass等细节具体且内部自洽。','{"independence": "单源（src-fc7ca176df63，2条互补L3）", "quality_density": "双版发布日期+目标人群+模型清单+Fast Pass+API Key细节具体", "recency": "2026年6月"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:25:55');
INSERT INTO "credibility_assessment" VALUES('cred-293ee5d70c1a','l2_finding','sf-2c6ff6787aea','medium','单一来源的Qoder身份与更名事实，含明确更名日期与6类产品矩阵，为可公开核验的产品事实。','{"independence": "单源（src-815dbcf6d1a6）", "quality_density": "更名日期2026-05-20+6类产品矩阵具体", "recency": "2026年5月"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:25:55');
INSERT INTO "credibility_assessment" VALUES('cred-cd9487a0bb8f','l2_finding','sf-0bea4f8fbd98','medium','单一来源的资源包定价机制，含具体价格、有效期、跨产品共享与折扣规则，可证伪且内部自洽。','{"independence": "单源（src-815dbcf6d1a6）", "quality_density": "价格/有效期/跨产品共享/80%折扣具体", "recency": "2026年"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:25:55');
INSERT INTO "credibility_assessment" VALUES('cred-b746a0597cb2','l2_finding','sf-e31352387a23','medium','单一 web 来源但信息密度高、细节具体（完整模型家族、模式划分、自定义模型桌面端专属、预置窗口不公开），逻辑契合主流编码平台的配额管理模式；缺独立交叉印证故未达 high。','{"independence": "单一来源 src-5143c8a8edfd，未经第二来源交叉印证", "quality_density": "列举具体模型名、模式与配置机制，可证伪、细节充分"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:25:55');
INSERT INTO "credibility_assessment" VALUES('cred-34f0cfd230b7','l2_finding','sf-b3fd255d855d','medium','单一 web 来源；描述的是明确、具体的平台行为（自动/手动压缩、新会话清空），逻辑自洽且符合主流 Agent 平台的上下文管理范式，但无独立第二来源印证。','{"independence": "单一来源 src-9e1192eb5de0", "quality_density": "行为机制描述具体（触发条件、压缩方式、会话隔离），可验证"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:25:55');
INSERT INTO "credibility_assessment" VALUES('cred-4ee74314f962','l2_finding','sf-ab3e900a71bd','medium','单一作者的一手实测，含可证伪的具体数字（发布日期、1M 上下文、21min vs 6min、10 万行项目）与明确比较基准（Claude Opus 4.8），信息密度与逻辑契合度高；但系单一评测者的主观+实测、未经多独立来源复核，且『基建差距而非能力差距』含主观判断，故 medium 而非 high。','{"independence": "单一来源 src-ecf96379cac9（单一作者实测），无独立第二评测交叉印证", "quality_density": "高密度、可证伪：发布日期、上下文长度、横向耗时与结果对比、短板均明确"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:25:55');
INSERT INTO "credibility_assessment" VALUES('cred-93e4197d384f','l1_viewpoint','vp-9429b34fef69','medium','三足鼎立格局与产品定位由3个分属不同产品的独立来源各自印证,非回音室;但cross_platform=1,证据局限于web单平台,缺社媒/独立测评二次验证','{"independence": "3源分别覆盖WorkBuddy/Trae/Qoder,各自独立观察,真实独立印证", "quality_density": "产品定位、能力清单、归属团队等细节充分可证伪", "recency": "均为2026年5–7月最新动态,时效性强"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:29:35');
INSERT INTO "credibility_assessment" VALUES('cred-a137f597a798','l1_viewpoint','vp-25c4acd6e2db','medium','转型趋势由3个分属不同产品的独立来源各自印证同一模式,构成真实独立印证而非回音室;但cross_platform=1(全web),计费细节多源自官方文档/产品分析,缺用户实测账单交叉','{"independence": "3源各覆盖一产品,独立显示同一切换,真实印证", "quality_density": "切换日期、套餐档位、系数数字等高度可证伪", "recency": "切换事件均为2026年2–7月,时效强"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:29:35');
INSERT INTO "credibility_assessment" VALUES('cred-d7d8c52fcce0','l1_viewpoint','vp-0d9d5a71da34','medium','因果逻辑由2–3个独立来源交叉印证(含Qoder涨价动作的间接佐证),逻辑自洽;但''成本倒逼''部分依赖厂商定价叙事,存在厂商为涨价/切制正名的利益偏向,需独立数据复核','{"independence": "Trae分析+Qoder涨价动作两个独立观察点指向同一逻辑,但两者均源自web分析侧", "quality_density": "含5–10倍成本差、10+次调用等可证伪量化细节", "recency": "论证针对2025–2026 Agent化窗口,时效匹配"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:29:35');
INSERT INTO "credibility_assessment" VALUES('cred-69ebaed9bb79','l1_viewpoint','vp-fdf878ea3fac','medium','双轨定价数字由3源交叉印证且为公开可核实的官方定价;但''购买力+竞争烈度''的解释属推断,缺厂商或第三方对定价逻辑的直接陈述','{"independence": "定价数字可被任一用户独立核验,3源一致", "quality_density": "具体到币种、档位、系数、有效期,密度高", "recency": "2026年5–7月现行定价,时效强"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:29:35');
INSERT INTO "credibility_assessment" VALUES('cred-e24b0a12055b','l1_viewpoint','vp-6b5a08d9ab67','medium','TRAE Work模型/上下文机制由2源印证;GLM-5.2测评源自单一独立实测但细节充分可证伪;整体限于web单平台(cross_platform=1),缺多平台独立验证','{"independence": "TRAE机制2源独立印证;GLM-5.2测评单源但为亲历实测", "quality_density": "含10万行实测、21vs6分钟、1M上下文等高密度可证伪细节", "recency": "GLM-5.2为2026-06最新事件,时效强"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:29:35');
INSERT INTO "credibility_assessment" VALUES('cred-c32e1c6daf88','l0_worldview','wv-e79b78c56197627b','medium','宏观命题由3个独立来源交叉印证的核心趋势(格局+转型+成本逻辑)支撑,逻辑链自洽且非回音室;但全部证据cross_platform=1(限web/官方文档侧),三条关键独立验证线(用户实测账单、第三方成本审计、社媒活人评价)均缺,故不上high','{"independence": "核心趋势由分属3产品的独立来源印证,但均来自web分析/官方文档同一信息模态", "quality_density": "定价数字、切换日期、成本倍数等高度可证伪,但''成本倒逼''解释含厂商叙事成分", "recency": "事件集中在2026年2–7月,主题快速演变,部分结论(如Trae Work国内版走向)可能短期失效"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:29:35');
INSERT INTO "credibility_assessment" VALUES('cred-02ab9ab2f85c','l3_claim','sc-37f4e8b87ccc','medium','TRAE 官方账号一手发布，信源权威性高；但正文因风控墙缺失，主张仅从标题提取，信息密度受限——无法验证具体条款、生效日期或配额细节，故降级为 medium。','{"independence": "一手官方信源，非转发，独立性强", "quality_density": "标题明确但缺乏正文细节，信息密度中等偏低", "recency": "帖子有活跃互动（赞178/评148），应为近期发布，时效性好"}','TRAE 官方账号直接发布，非二次传播',0,NULL,'active',NULL,'2026-07-06 13:49:05');
INSERT INTO "credibility_assessment" VALUES('cred-fb89cf3f83a0','l3_claim','sc-39a1a72fd163','medium','提供了具体参数（750B、1M tokens）和大致性能比例（1% 差距、1/5 成本），信息密度尚可；但未指明 benchmark 名称、未给出评测方法论、无第三方验证链接，且来源为单条社交媒体推文，独立性有限，存在选择性引用或推广包装的可能。','{"independence": "单一 X 推文来源，未引用评测报告或第三方验证链接；无法确认是否存在独立评测", "quality_density": "有具体数字（750B 参数、1M token 上下文、~1% 性能差距、~1/5 成本）但核心 benchmark 未具名，缺少可复现信息", "recency": "模型发布类信息时效性要求高；该推文引用的是近期发布，但 AI 领域变化极快，需持续跟踪"}','仅一条社交平台推文，作者可能是 AI 领域关注者或利益相关方；未找到该推文引用的独立 benchmark 报告链接',0,NULL,'active',NULL,'2026-07-06 13:49:05');
INSERT INTO "credibility_assessment" VALUES('cred-c1e0aee490c0','l3_claim','sc-41d95da883f6','low','agent distill','{"phase": "distill"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:49:05');
INSERT INTO "credibility_assessment" VALUES('cred-9fc3c3f5b7f7','l3_claim','sc-5143c8a8edfd','high','TRAE 官方文档对自身产品的功能与模型阵容作一手陈述，可证伪、细节具体（具名模型、模式划分、配置项、平台限制）；「上下文窗口未公开」是对文档内容的直接观察而非传闻。','{"independence": "第一方官方文档，权威描述自身产品行为", "quality_density": "高：具名模型清单 + 明确的配置项与平台限制（桌面端/本地专属）", "recency": "现行产品文档，截至抓取时有效"}','一手来源自述其产品；「上下文窗口未公开」属观察性结论，由文档缺失直接支撑。',0,NULL,'active',NULL,'2026-07-06 13:49:05');
INSERT INTO "credibility_assessment" VALUES('cred-fe58b15c2fcc','l3_claim','sc-6c703319eb56','medium','规格数字具体可验证（可证伪性高），但发布者为个人X账号非智谱官方，缺乏直接来源链接，需独立印证确认参数和基准数据。','{"independence": "单一来源，非官方发布，信息可能来自二手转述", "quality_density": "高密度具体数字（744B/40B/256K/131K），可证伪性强", "recency": "时效性高，涉及最新模型发布信息"}','需至少一个独立来源（官方公告或可信科技媒体）印证参数与基准数据',0,NULL,'active',NULL,'2026-07-06 13:49:05');
INSERT INTO "credibility_assessment" VALUES('cred-8b64582c1960','l3_claim','sc-762619a5e098','medium','具体技术参数（bpw量化精度、推理速度、上下文长度）可被独立复现，信息密度高；但为单一个人报告，未经独立验证，且未公开硬件规格与fork细节。','{"independence": "单源个人推文，无独立交叉验证", "quality_density": "信息密度高：含量化精度(3.6 bpw)、推理速度(13 tok/s)、上下文长度(~100k)、技术手段(DSA)，均可复现验证", "recency": "推文时效性强，模型版本 GLM 5.2 为最新发布，信息当前有效"}','仅为单一用户实操报告，非第三方评测或官方声明',0,NULL,'active',NULL,'2026-07-06 13:49:05');
INSERT INTO "credibility_assessment" VALUES('cred-d4449766a3cb','l3_claim','sc-9e1192eb5de0','high','TRAE 官方文档作为一手来源，对其产品上下文压缩机制的描述具权威性与高信息密度、可证伪；末尾『可能不暴露原生窗口』为研究者推断而非文档陈述，已标注待印证。','{"independence": "厂商官方文档，单一一手来源；对自家产品机制描述具权威性，但非多源独立印证", "quality_density": "描述具体机制（触发条件/行为/适用范围/UI 反馈），信息密度高、可证伪", "recency": "现行官方文档，信息时效有效"}','厂商自文档，对产品行为事实权威；但仅单一来源，关于上下文上限是否等于模型原生窗口的推断需其它来源佐证。',0,NULL,'active',NULL,'2026-07-06 13:49:05');
INSERT INTO "credibility_assessment" VALUES('cred-d3ce33d6010a','l3_claim','sc-a7994267d68a','low','正文缺失，仅有列表卡片标题；无法验证作者的具体测试方法、prompt设计、通过率数据和结论是否有偏。B类证据，信息密度极低。','{"independence": "单源，无法交叉验证", "quality_density": "极低——仅有标题无正文，实际测试结果不可知", "recency": "未知发布时间，时效性无法判断"}','单条小红书笔记，无独立第二来源佐证其具体结论',0,NULL,'active',NULL,'2026-07-06 13:49:05');
INSERT INTO "credibility_assessment" VALUES('cred-3bda77963da6','l3_claim','sc-d4224cf9f130','medium','宣传性帖文，作者身份未验证，未附独立基准测试链接；但主张具体可证伪（1M context、coding 性能对标 Opus），有一定信息密度。','{"independence": "单一 X 帖文，未发现作者引述其他独立来源或评测数据", "quality_density": "主张具体但缺乏量化证据（如 benchmark 分数），宣传语气降低了信息密度", "recency": "帖文时效性需由上下文判断，模型发布信息通常在短期内有效"}','仅一条来源，无法交叉验证；若后续有独立评测或官方发布确认，可信度可上调',0,NULL,'active',NULL,'2026-07-06 13:49:05');
INSERT INTO "credibility_assessment" VALUES('cred-b1f57f49fcde','l3_claim','sc-ecf96379cac9','medium','含一手实测计时数据(21min vs 6min,可证伪、高密度)且时效新鲜(约3周前),但系单来源,核心benchmark(1M上下文、接近Claude)源自智谱官方发布未独立复测。','{"independence": "单一来源(头条号''观察者'');发布事实与benchmark数字追溯至智谱官方公告,仅计时机比为作者一手;无第二独立来源印证。", "quality_density": "高:具体可证伪数字(1M/400-500K上下文、21分钟vs6分钟、10万行代码、MIT协议、2026-06-13发布日),非空泛口号。", "recency": "2026-06-13发布,距今约3周,快变主题(AI模型)下仍有效;API''下周上线''为预测性陈述需后续校验。"}','非纯回音室——作者提供了一手实测计时对比作为增量;但官方能力声明(1M可用、幻觉极低、接近Claude)无独立交叉验证,需在aggregate阶段与其它实测来源印证后方可升为high。',0,NULL,'active',NULL,'2026-07-06 13:49:05');
INSERT INTO "credibility_assessment" VALUES('cred-1d879a2ea8bf','l2_finding','sf-1ebf4def9325','medium','单源web文章，但信息密度高、包含具体产品细节和定位描述，可证伪性强；时效性好（2026年7月产品动态）。','{"independence": "单源，无跨平台印证", "quality_density": "高密度——具体产品名、能力列表、竞品对比定位，可独立验证", "recency": "2026年7月有效"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-b005370308cd','l2_finding','sf-74885b5c11b2','medium','同为单源（同一web来源的两条L3合并），但数据具体可验证（价格数字、模型系数、消耗量级）；无独立第二源印证。','{"independence": "两条L3来自同一来源，无跨源印证", "quality_density": "高密度——具体价格、积分数字、模型系数值，均为可验证数据点", "recency": "2026年7月1日起生效，时效性极佳"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-effa952555f3','l2_finding','sf-e2cbc7860cb4','medium','单源但包含可验证的具体发布日期和域名，产品线划分属于公开信息。','{"independence": "单源，无跨平台印证", "quality_density": "高——具体日期、域名、产品演进路径清晰", "recency": "2025年1月至2026年6月，时效性好"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-2c4aafef2972','l2_finding','sf-0836d368eced','medium','同一web来源的两条L3合并，信息具体（日期、套餐名、模型名、权益缩水比例），但无独立第二源印证权益缩水测算。','{"independence": "两条L3来自同一来源，无跨源印证", "quality_density": "高——具体切换日期、五档套餐名、模型列表、缩水比例（1/5），可验证", "recency": "2026年2月-6月，时效性好"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-44ac73cb8055','l2_finding','sf-7c1d68be46dd','medium','分析性主张而非可测量事实，但推理链完整且有行业案例支撑（Cursor、GitHub Copilot），逻辑自洽；单源分析文章。','{"independence": "单源分析，5条理由来自同一作者的归纳", "quality_density": "高——5条具体设计逻辑，每条附带行业参照或用户心理依据", "recency": "分析2025年初至2026年的行业演进，时效性好"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-83786b1d28ce','l2_finding','sf-a52a59a1bfd6','medium','分析性主张，论据链清晰（上下文窗口扩展→Agent多轮调用→交叉补贴破裂），与Trae国际版和Cursor的实际计费切换可相互印证；单源但逻辑可独立验证。','{"independence": "单源分析，但引用了可验证的行业事实（Cursor/Trae切换Token制）", "quality_density": "高——具体技术参数（8k→128k-1M+）、成本倍数（5-10x）、行为差异量化（几十倍）", "recency": "描述2025-2026年行业趋势，时效性好"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-f13e0c016968','l2_finding','sf-7aedb1d4cdc7','medium','前瞻性分析而非确定事实，但推理基于Trae Work实际产品定位和国内市场策略，与Trae Work当前免费策略一致。','{"independence": "单源分析", "quality_density": "中高——三条原因有产品差异（Work vs Code模式）和市场策略支撑，但''未来可能需要调整''属于推测", "recency": "2026年6月产品现状分析，时效性好"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-54640fab98a5','l2_finding','sf-989d277a05da','medium','单源但包含可验证的具体更名日期、产品矩阵列表；Qoder是阿里公开产品，核心事实可交叉验证。','{"independence": "单源，但产品矩阵属于公开信息可多渠道验证", "quality_density": "高——具体日期（2026.5.20）、完整产品列表（6个产品线）", "recency": "2026年5月更名信息，时效性极佳"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-485ecb3adee1','l2_finding','sf-ccfdcb0ee461','medium','同一web来源的两条L3合并，定价数字具体可验证（美元/人民币价格、Credits数量、有效期），但无独立第二源印证；Qoder官网可验证核心定价。','{"independence": "两条L3来自同一来源，无跨源印证", "quality_density": "高——具体价格数字、Credits数、有效期、国内外价格比例（40%），均为硬数据", "recency": "2026年5月更名后定价，时效性极佳"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-8326d31e45f6','l2_finding','sf-853c27b9d8ae','medium','单源但包含详细功能清单和具体折扣数值（80%），属于Qoder产品机制描述，官网可验证核心规则。','{"independence": "单源，无跨平台印证", "quality_density": "高——功能分级清晰（免费/收费边界明确）、具体模型列表、折扣数字（80%）", "recency": "2026年Qoder产品机制，时效性好"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-78c1be63d261','l2_finding','sf-1f18e3b7eb5d','medium','分析性主张——涨价的''事实''部分（价格涨幅、企业客户数）可验证，但''涨价逻辑''部分（迁移成本锁定、算力成本驱动）是来源方的归因分析。','{"independence": "单源分析", "quality_density": "高——具体涨价幅度（25%）、旧新价格对照、点名企业客户、双重归因（锁定+成本）", "recency": "2026年5月更名+调价，时效性极佳"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-b8ba47bf7e9c','l2_finding','sf-17f0fcdf301f','medium','单源 web 文档，描述细致、可证伪（具体行为而非模糊宣传），但缺乏第二独立来源印证','{"independence": "单源，无独立印证", "quality_density": "高——描述了具体机制（自动触发条件、手动触发路径、新会话行为），可证伪", "recency": "当前产品文档，未发现过期信号"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-fef1249db35e','l2_finding','sf-fb8c14f9e946','medium','单源但信息密度极高（精确模型列表 + 具体行为描述），来源为官方文档级别；上下文窗口不透明这一发现本身是重要信号','{"independence": "单源，无独立印证", "quality_density": "高——具体模型名称、分类逻辑、配置行为均为可验证的精确陈述", "recency": "当前产品状态，模型列表为新近模型，未发现过期信号"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-ad738edae4c4','l2_finding','sf-6417b2672a89','low','小红书单源信号，缺乏具体细节（无时间线、无具体配额数字），属前瞻性传闻而非已确认事实','{"independence": "单源社媒，无独立印证", "quality_density": "低——表述模糊（''即将''、''可能''），无可证伪细节", "recency": "前瞻性信号，时效性当前有效但待后续验证"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-e191d3f17d34','l2_finding','sf-75019a4ba8bc','high','三个独立来源（均为 X 平台）在核心事实上高度一致——开源 MIT、MoE 架构、接近 Claude Opus 4.8、成本显著更低；参数和窗口的细微差异不削弱核心主张','{"independence": "三个独立 X 来源，非同一推文的转发链", "quality_density": "高——sc-6c703319eb56 提供精确架构参数（744B/40B MoE、131K 输出上限），sc-39a1a72fd163 提供定量 benchmark 差距（约 1%）和成本比（1/5），均可证伪", "recency": "GLM-5.2 为 2026 年 6 月发布，当前高度时效"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-537ee4413059','l2_finding','sf-c859e2b530af','medium','sc-ecf96379cac9 来自 web 深度实测（10 万行代码项目、有时间对比数据），质量高且可复现；sc-a7994267d68a 因小红书风控内容缺失，仅作为存在前端工程测试信号的旁证，不贡献实质证据','{"independence": "两条来源平台不同（web + 小红书），但 sc-a7994267d68a 内容缺失无法独立验证", "quality_density": "sc-ecf96379cac9 极高——具体项目规模、耗时对比、瓶颈归因均清晰；sc-a7994267d68a 极低——仅有卡片标题", "recency": "2026 年 6 月实测，当前有效"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-eab82627b3b8','l2_finding','sf-1094ee77ffd9','medium','单源 X 平台，但技术细节极其具体（量化精度 3.6 bpw、推理速度 13 tok/s、DSA 长上下文方案），可复现验证；缺乏第二独立来源确认','{"independence": "单源，无独立印证", "quality_density": "高——精确的量化参数、推理速度、技术方案命名，均为可复现的技术陈述", "recency": "GLM-5.2 发布后的社区量化实践，时效有效"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:50:17');
INSERT INTO "credibility_assessment" VALUES('cred-c3b674e215ca','l1_viewpoint','vp-4270fcf4920f','high','三家产品定位和功能描述来自各自官方定价页/产品文档的直接蒸馏，L2层corroboration_count多为3（三个独立web来源交叉验证），信息密度高、细节可证伪，时效性为2026年最新状态。','{"independence": "三个web来源分别覆盖三家产品，相互独立；但三家信息均来自web同一渠道类型，缺乏社媒/用户端独立验证", "quality_density": "产品功能、定价、时间点均为可证伪的硬信息，非泛化描述", "recency": "2026年5-7月最新状态"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:52:32');
INSERT INTO "credibility_assessment" VALUES('cred-b983c849461c','l1_viewpoint','vp-0acc9ca08e31','high','计费模式细节（积分系数、Credits消耗规则、折扣策略）均来自各产品官方定价文档的直接蒸馏，信息精确可验证。','{"independence": "三家产品的计费信息分别来自独立web来源，相互可交叉验证", "quality_density": "计费系数、Credits数值、有效期等均为硬数据，高度可证伪", "recency": "2026年6-7月最新计费政策"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:52:32');
INSERT INTO "credibility_assessment" VALUES('cred-a1a2b232a8bf','l1_viewpoint','vp-8de47014d3f3','high','技术驱动力（上下文窗口扩大、Agent多轮调用、模型成本差异）为可验证的行业技术事实，Trae国际版切换Token制的具体时间点和Qoder涨价幅度均为可证伪的硬数据。','{"independence": "两个web来源（Trae分析和Qoder报道）从不同产品角度独立印证同一成本上升逻辑", "quality_density": "包含具体数值（窗口大小、调用次数、成本倍数、涨价百分比），高度可证伪", "recency": "2026年2-7月最新动态"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:52:32');
INSERT INTO "credibility_assessment" VALUES('cred-65f8f1a4c7f0','l1_viewpoint','vp-893aad9ec652','medium','定价对比数据确凿（¥59 vs $20），但''中国购买力水平''的解释和''张力''判断依赖推理链条而非直接证据；需要用户端付费意愿、转化率数据才能将判断从plausible提升为established。','{"independence": "三个web来源一致报告国内定价低于全球", "quality_density": "定价数据为硬数字，但价格-可持续性因果推理的证据密度不足", "recency": "2026年最新定价"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:52:32');
INSERT INTO "credibility_assessment" VALUES('cred-bceb94266502','l1_viewpoint','vp-06a925264a14','medium','TRAE Work模型列表和上下文压缩机制来自官方文档的直接蒸馏（信息可靠），但GLM-5.2性能评估为单一来源的开发者实测（corroboration_count=1），虽然信息密度高（具体性能对比和数字）但缺乏独立复现。','{"independence": "模型列表和GLM-5.2性能来自不同来源；GLM-5.2基础信息（架构、参数、MIT协议）有3源印证，但性能实测为单源", "quality_density": "高——具体模型名称、上下文压缩机制描述、性能对比数字均可证伪", "recency": "2026年6月最新信息"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:52:32');
INSERT INTO "credibility_assessment" VALUES('cred-5d07c176f6d7','l0_worldview','wv-b0fc9a7b98d15de5','medium','核心事实（产品定位、定价、计费模式转型时间点）来自多源web交叉验证，可信度高；但关键推理链条（成本倒逼因果关系、定价可持续性判断）依赖厂商自述的''成本叙事''而缺乏独立审计验证，且完全缺失社媒端用户活人反馈作为独立验证源。','{"independence": "三个web来源分别覆盖三家产品，在平台层面相互独立；但渠道类型单一（全web），缺失社媒端独立验证是结构性的可信度缺陷", "quality_density": "产品计费细节信息密度高；但成本-定价因果关系的证据密度不足（推理多、硬数据少）", "recency": "2026年5-7月最新动态，时效性良好"}',NULL,0,NULL,'active',NULL,'2026-07-06 13:52:32');
