INSERT INTO "knowledge_change_log" VALUES(61,'l3_claim','sc-5143c8a8edfd','*','update','{"id": "sc-5143c8a8edfd", "facet": null, "proposition": "TRAE Work 同时支持预置模型与自定义模型；预置模型按 Work/Code 两套模式划分（Work 含 TRAE Auto Model、Doubao-Seed-2.1-Pro/Turbo、MiniMax-M3/M2.7、GLM-5.2/5-Turbo/5、DeepSeek-V4-Pro/Flash、Kimi-K2.7-Code/K2.6；Code 模式另加 GLM-5.1、GLM-5V-Turbo、Qwen3.7/3.6-Plus），但预置模型（含 GLM-5.2）的上下文窗口大小在官方文档中未公开——仅自定义模型允许用户手动配置输入/输出 Token 上限，预置配额由 TRAE Work 内部管理且不对用户暴露；自定义模型为桌面端本地环境专属。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-5143c8a8edfd", "source_ref_ids": "[\"src-5143c8a8edfd\"]", "verbatim_excerpt": "预置模型的上下文窗口大小在官方文档中未明确说明/未公开；仅「添加自定义模型」时允许用户手动配置「上下文窗口-输入」和「上下文窗口-输出」", "cached_text_hash": "19e4b778919c6fbd2e1732bbf7e0448498c30725aec2496c28d63f8e5aff8afc", "analysis_note": "对 coding/work 产品配额研究而言，最有价值的信号是「预置模型上下文窗口不透明」——用户无法从文档直接比较 GLM-5.2 等预置模型的有效上下文配额，需以实测或计费行为推断；模型阵容清单为辅证。", "filter_trace": "{\"independence\": \"第一方官方文档，权威描述自身产品行为\", \"quality_density\": \"高：具名模型清单 + 明确的配置项与平台限制（桌面端/本地专属）\", \"recency\": \"现行产品文档，截至抓取时有效\"}", "debate_trace": null, "credibility_id": "cred-2b6a58ff0b53", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-07-06 13:17:14", "updated_at": "2026-07-06 13:22:22", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-5143c8a8edfd", "facet": null, "proposition": "TRAE Work 同时支持预置模型与自定义模型；预置模型按 Work/Code 两套模式划分（Work 含 TRAE Auto Model、Doubao-Seed-2.1-Pro/Turbo、MiniMax-M3/M2.7、GLM-5.2/5-Turbo/5、DeepSeek-V4-Pro/Flash、Kimi-K2.7-Code/K2.6；Code 模式另加 GLM-5.1、GLM-5V-Turbo、Qwen3.7/3.6-Plus），但预置模型（含 GLM-5.2）的上下文窗口大小在官方文档中未公开——仅自定义模型允许用户手动配置输入/输出 Token 上限，预置配额由 TRAE Work 内部管理且不对用户暴露；自定义模型为桌面端本地环境专属。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-5143c8a8edfd", "source_ref_ids": "[\"src-5143c8a8edfd\"]", "verbatim_excerpt": "预置模型的上下文窗口大小在官方文档中未明确说明/未公开；仅「添加自定义模型」时允许用户手动配置「上下文窗口-输入」和「上下文窗口-输出」", "cached_text_hash": "19e4b778919c6fbd2e1732bbf7e0448498c30725aec2496c28d63f8e5aff8afc", "analysis_note": "对 coding/work 产品配额研究而言，最有价值的信号是「预置模型上下文窗口不透明」——用户无法从文档直接比较 GLM-5.2 等预置模型的有效上下文配额，需以实测或计费行为推断；模型阵容清单为辅证。", "filter_trace": "{\"independence\": \"第一方官方文档，权威描述自身产品行为\", \"quality_density\": \"高：具名模型清单 + 明确的配置项与平台限制（桌面端/本地专属）\", \"recency\": \"现行产品文档，截至抓取时有效\"}", "debate_trace": null, "credibility_id": "cred-9fc3c3f5b7f7", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-07-06 13:17:14", "updated_at": "2026-07-06 13:49:05", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-07-06 13:49:05',NULL);
