INSERT INTO "knowledge_change_log" VALUES(63,'l3_claim','sc-762619a5e098','*','insert',NULL,NULL,'kind=fact facet=None','condense-distill','2026-07-06 13:49:05',NULL);
INSERT INTO "knowledge_change_log" VALUES(64,'l3_claim','sc-9e1192eb5de0','*','update','{"id": "sc-9e1192eb5de0", "facet": null, "proposition": "TRAE Work（仅 SOLO Agent）为每个对话维护独立的上下文窗口，当累积上下文超过平台允许的上限时自动触发（亦可手动触发）上下文压缩，通过移除冗余、保留关键内容以维持输出质量——而非抛错报错；开启新会话则清空先前上下文。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-9e1192eb5de0", "source_ref_ids": "[\"src-9e1192eb5de0\"]", "verbatim_excerpt": "使用限制：仅适用于SOLO Agent（即TRAE Work）……当使用的上下文超过允许的上下文窗口时，系统自动触发一次上下文压缩……通过压缩移除冗余信息仅保留关键内容，确保AI聚焦核心上下文并维持输出质量。", "cached_text_hash": "5c6989a24555f530cd50edb30c6adfaefecab6977afb441cc8ff314eb98871fd", "analysis_note": "文档未说明该「允许的上下文窗口」是否等于模型原生上下文（如 GLM-5.2 的 1M）；compaction 机制的存在表明平台对上下文做了上限管理，可能未暴露模型原生完整窗口——此点为研究者推断，非文档直接陈述，需其它来源印证。", "filter_trace": "{\"independence\": \"厂商官方文档，单一一手来源；对自家产品机制描述具权威性，但非多源独立印证\", \"quality_density\": \"描述具体机制（触发条件/行为/适用范围/UI 反馈），信息密度高、可证伪\", \"recency\": \"现行官方文档，信息时效有效\"}", "debate_trace": null, "credibility_id": "cred-2bd027f08737", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-07-06 13:17:14", "updated_at": "2026-07-06 13:22:22", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-9e1192eb5de0", "facet": null, "proposition": "TRAE Work（仅 SOLO Agent）为每个对话维护独立的上下文窗口，当累积上下文超过平台允许的上限时自动触发（亦可手动触发）上下文压缩，通过移除冗余、保留关键内容以维持输出质量——而非抛错报错；开启新会话则清空先前上下文。", "claim_kind": "fact", "source_kind": "article", "single_source_ref_id": "src-9e1192eb5de0", "source_ref_ids": "[\"src-9e1192eb5de0\"]", "verbatim_excerpt": "使用限制：仅适用于SOLO Agent（即TRAE Work）……当使用的上下文超过允许的上下文窗口时，系统自动触发一次上下文压缩……通过压缩移除冗余信息仅保留关键内容，确保AI聚焦核心上下文并维持输出质量。", "cached_text_hash": "5c6989a24555f530cd50edb30c6adfaefecab6977afb441cc8ff314eb98871fd", "analysis_note": "文档未说明该「允许的上下文窗口」是否等于模型原生上下文（如 GLM-5.2 的 1M）；compaction 机制的存在表明平台对上下文做了上限管理，可能未暴露模型原生完整窗口——此点为研究者推断，非文档直接陈述，需其它来源印证。", "filter_trace": "{\"independence\": \"厂商官方文档，单一一手来源；对自家产品机制描述具权威性，但非多源独立印证\", \"quality_density\": \"描述具体机制（触发条件/行为/适用范围/UI 反馈），信息密度高、可证伪\", \"recency\": \"现行官方文档，信息时效有效\"}", "debate_trace": null, "credibility_id": "cred-d4449766a3cb", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-07-06 13:17:14", "updated_at": "2026-07-06 13:49:05", "updated_by": "condense-distill", "audit_note": null}','kind=fact facet=None','condense-distill','2026-07-06 13:49:05',NULL);
