INSERT INTO "knowledge_change_log" VALUES(66,'l3_claim','sc-d4224cf9f130','*','insert',NULL,NULL,'kind=analysis facet=None','condense-distill','2026-07-06 13:49:05',NULL);
INSERT INTO "knowledge_change_log" VALUES(67,'l3_claim','sc-ecf96379cac9','*','update','{"id": "sc-ecf96379cac9", "facet": null, "proposition": "智谱于2026年6月13日向GLM Coding Plan全量用户(Lite/Pro/Max/团队版)开放GLM-5.2——其迄今最强开源模型(MIT协议):支持真正可用的1M上下文、400-500K下指令遵循接近Claude、幻觉极低、长程任务领先;实测在10万行代码项目排查中结果与Claude Opus 4.8几乎一致但慢2倍多(21分钟 vs 6分钟),作者判定为算力基建差距而非模型能力差距;最大短板是不支持多模态,Coding Plan仍限额需每天抢,反映国产infra/算力差距。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-ecf96379cac9", "source_ref_ids": "[\"src-ecf96379cac9\"]", "verbatim_excerpt": "稳但慢——在10万行代码项目中排查监控故障全程21分钟（Claude Opus 4.8 fast模式6分钟），过程结果几乎一样但速度差2倍多，这是算力基建差距而非模型能力差距。", "cached_text_hash": "945818fc55f83b5ed0f9330db78ecdd6fcb07aeeecf0bf2641b9450bc354be64", "analysis_note": "原文混合三类内容:(1)官方发布事实(日期、版本、MIT开源、1M上下文);(2)作者一手实测(10万行代码排查的21分钟 vs 6分钟计时对比)——这是本文相对通稿的增量证据;(3)解读性判断(''算力基建差距而非模型能力差距''、''Coding Plan限额反映infra差距'')。可信度主要依赖第(2)类一手数据,官方benchmark数字未经独立复测。", "filter_trace": "{\"independence\": \"单一来源(头条号''观察者'');发布事实与benchmark数字追溯至智谱官方公告,仅计时机比为作者一手;无第二独立来源印证。\", \"quality_density\": \"高:具体可证伪数字(1M/400-500K上下文、21分钟vs6分钟、10万行代码、MIT协议、2026-06-13发布日),非空泛口号。\", \"recency\": \"2026-06-13发布,距今约3周,快变主题(AI模型)下仍有效;API''下周上线''为预测性陈述需后续校验。\"}", "debate_trace": null, "credibility_id": "cred-89b3b04dd915", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-07-06 13:17:14", "updated_at": "2026-07-06 13:22:22", "updated_by": "condense-distill", "audit_note": null}','{"id": "sc-ecf96379cac9", "facet": null, "proposition": "智谱于2026年6月13日向GLM Coding Plan全量用户(Lite/Pro/Max/团队版)开放GLM-5.2——其迄今最强开源模型(MIT协议):支持真正可用的1M上下文、400-500K下指令遵循接近Claude、幻觉极低、长程任务领先;实测在10万行代码项目排查中结果与Claude Opus 4.8几乎一致但慢2倍多(21分钟 vs 6分钟),作者判定为算力基建差距而非模型能力差距;最大短板是不支持多模态,Coding Plan仍限额需每天抢,反映国产infra/算力差距。", "claim_kind": "analysis", "source_kind": "article", "single_source_ref_id": "src-ecf96379cac9", "source_ref_ids": "[\"src-ecf96379cac9\"]", "verbatim_excerpt": "稳但慢——在10万行代码项目中排查监控故障全程21分钟（Claude Opus 4.8 fast模式6分钟），过程结果几乎一样但速度差2倍多，这是算力基建差距而非模型能力差距。", "cached_text_hash": "945818fc55f83b5ed0f9330db78ecdd6fcb07aeeecf0bf2641b9450bc354be64", "analysis_note": "原文混合三类内容:(1)官方发布事实(日期、版本、MIT开源、1M上下文);(2)作者一手实测(10万行代码排查的21分钟 vs 6分钟计时对比)——这是本文相对通稿的增量证据;(3)解读性判断(''算力基建差距而非模型能力差距''、''Coding Plan限额反映infra差距'')。可信度主要依赖第(2)类一手数据,官方benchmark数字未经独立复测。", "filter_trace": "{\"independence\": \"单一来源(头条号''观察者'');发布事实与benchmark数字追溯至智谱官方公告,仅计时机比为作者一手;无第二独立来源印证。\", \"quality_density\": \"高:具体可证伪数字(1M/400-500K上下文、21分钟vs6分钟、10万行代码、MIT协议、2026-06-13发布日),非空泛口号。\", \"recency\": \"2026-06-13发布,距今约3周,快变主题(AI模型)下仍有效;API''下周上线''为预测性陈述需后续校验。\"}", "debate_trace": null, "credibility_id": "cred-b1f57f49fcde", "parent_l2_id": null, "lifecycle": null, "status": "active", "run_id": null, "context_snapshot_id": null, "context_hash": null, "created_at": "2026-07-06 13:17:14", "updated_at": "2026-07-06 13:49:05", "updated_by": "condense-distill", "audit_note": null}','kind=analysis facet=None','condense-distill','2026-07-06 13:49:05',NULL);
