INSERT INTO "l2_finding" VALUES('sf-0836d368eced','f_ai_coding_work_vs_vs_token','fact','Trae国际版已于2026年2月24日从请求次数制切换为Token计费（五档套餐Free/Lite/Pro/Pro+/Ultra），用户测算Pro用户实际权益缩水至约1/5；国内版Trae Work目前仍采用对话次数制（近期从每日限额改为每周限额），免费提供Doubao Seed 2.1 Pro/2.1 Turbo、MiniMax、GLM等模型，Pro版有Fast Pass优先队列，支持自定义API Key接入。',NULL,NULL,NULL,NULL,NULL,1,1,'["web"]',NULL,'["src-fc7ca176df63"]','cred-2c4aafef2972','["sc-5021cf331a20", "sc-ac65832dcadf"]',NULL,'active',NULL,NULL,NULL,'2026-07-06 13:50:17','2026-07-06 13:50:17','condense-aggregate',NULL);
INSERT INTO "l2_finding" VALUES('sf-7c1d68be46dd','f_ai_coding_work_vs_vs_token','claim','AI编程工具早期采用请求次数制而非Token制的核心设计逻辑包括：(1)Token是技术概念普通用户难理解，''X次/月''符合SaaS订阅心智，获客转化率更高；(2)2025年初模型上下文窗口小、Agent能力弱，单次请求token消耗差异不大；(3)Cursor早期Pro 500次快速请求、GitHub Copilot长期无限次是行业惯例；(4)产品快速迭代期粗粒度计费避免频繁调价；(5)避免用户的''Token焦虑''心理。',NULL,NULL,NULL,NULL,NULL,1,1,'["web"]',NULL,'["src-fc7ca176df63"]','cred-44ac73cb8055','["sc-542bd42e1250"]',NULL,'active',NULL,NULL,NULL,'2026-07-06 13:50:17','2026-07-06 13:50:17','condense-aggregate',NULL);
INSERT INTO "l2_finding" VALUES('sf-a52a59a1bfd6','f_ai_coding_work_vs_vs_token','claim','请求次数制不可持续的根本原因是成本倒逼：上下文窗口从8k/32k扩展到128k-1M+、Agent模式下单请求触发10+次模型调用、不同模型成本差5-10倍、重度用户单次会话token量是轻度用户几十倍，导致重度用户对轻度用户的交叉补贴不可持续——这也是Trae国际版和Cursor改Token制的直接原因。',NULL,NULL,NULL,NULL,NULL,1,1,'["web"]',NULL,'["src-fc7ca176df63"]','cred-83786b1d28ce','["sc-530a69a57ca6"]',NULL,'active',NULL,NULL,NULL,'2026-07-06 13:50:17','2026-07-06 13:50:17','condense-aggregate',NULL);
INSERT INTO "l2_finding" VALUES('sf-7aedb1d4cdc7','f_ai_coding_work_vs_vs_token','claim','Trae Work国内版暂时保留次数制的原因：目标用户更广泛含非技术用户（对Token接受度低）、Work/Design模式单次token消耗比Code模式可控、国内市场主打''免费够用''用户增长策略；但随着Agent能力增强单次对话实际成本上升，未来可能需要调整计费策略。',NULL,NULL,NULL,NULL,NULL,1,1,'["web"]',NULL,'["src-fc7ca176df63"]','cred-f13e0c016968','["sc-034d1a3ee08f"]',NULL,'active',NULL,NULL,NULL,'2026-07-06 13:50:17','2026-07-06 13:50:17','condense-aggregate',NULL);
