INSERT INTO "l2_finding" VALUES('sf-ccfdcb0ee461','f_ai_coding_work_vs_vs_token','figure','Qoder定价体系：全球版Pro $20/月(2000 Credits)、Pro+ $60/月(6000 Credits)，国内版约为全球版40%（个人Pro ¥59/月、Pro+ ¥169/月），企业标准版¥99/席位/月、VPC版¥199/席位/月；资源包个人¥40/1000 Credits(1个月有效)、企业¥80/2000 Credits(3个月有效)，到期清零，单价比套餐内高以鼓励订阅而非按量购买；新用户2周Pro试用+1000 Credits。',NULL,NULL,NULL,NULL,NULL,1,1,'["web"]',NULL,'["src-815dbcf6d1a6"]','cred-485ecb3adee1','["sc-d5719f9dd8f0", "sc-89233a8e21cf"]',NULL,'active',NULL,NULL,NULL,'2026-07-06 13:50:17','2026-07-06 13:50:17','condense-aggregate',NULL);
