INSERT INTO "l2_finding" VALUES('sf-17f0fcdf301f','_unfileted','fact','TRAE Work（SOLO Agent）为每个对话维护独立的上下文窗口，当累积上下文超过平台允许的上限时自动触发上下文压缩（移除冗余、保留关键内容）以维持输出质量，而非抛错报错；用户也可手动触发压缩，开启新会话则清空先前上下文。',NULL,NULL,NULL,NULL,NULL,1,1,'["web"]',NULL,'["src-9e1192eb5de0"]','cred-b8ba47bf7e9c','["sc-9e1192eb5de0"]',NULL,'active',NULL,NULL,NULL,'2026-07-06 13:50:17','2026-07-06 13:50:17','condense-aggregate',NULL);
INSERT INTO "l2_finding" VALUES('sf-fb8c14f9e946','_unfileted','fact','TRAE Work 同时支持预置模型与自定义模型，预置模型按 Work/Code 两套模式划分（Work 含 TRAE Auto Model、Doubao-Seed-2.1-Pro/Turbo、MiniMax-M3/M2.7、GLM-5.2/5-Turbo/5、DeepSeek-V4-Pro/Flash、Kimi-K2.7-Code/K2.6；Code 另加 GLM-5.1、GLM-5V-Turbo、Qwen3.7/3.6-Plus），但预置模型的上下文窗口大小在官方文档中未公开——仅自定义模型允许用户手动配置输入/输出 Token 上限，预置配额由平台内部管理且不对用户暴露；自定义模型为桌面端本地环境专属。',NULL,NULL,NULL,NULL,NULL,1,1,'["web"]',NULL,'["src-5143c8a8edfd"]','cred-fef1249db35e','["sc-5143c8a8edfd"]',NULL,'active',NULL,NULL,NULL,'2026-07-06 13:50:17','2026-07-06 13:50:17','condense-aggregate',NULL);
INSERT INTO "l2_finding" VALUES('sf-6417b2672a89','_unfileted','trend','TRAE 国际版即将升级计费方案，可能涉及上下文配额调整',NULL,NULL,NULL,NULL,NULL,1,1,'["xiaohongshu"]',NULL,'["src-37f4e8b87ccc"]','cred-ad738edae4c4','["sc-37f4e8b87ccc"]',NULL,'active',NULL,NULL,NULL,'2026-07-06 13:50:17','2026-07-06 13:50:17','condense-aggregate',NULL);
INSERT INTO "l2_finding" VALUES('sf-75019a4ba8bc','_unfileted','fact','GLM-5.2 是智谱 AI 的开源旗舰模型，采用 MoE 架构（总参数约 744B–750B，每 token 激活约 40B），以 MIT 许可证开放权重；在关键 agentic 与编程基准上表现接近甚至部分超越 Claude Opus 4.8，成本约为其五分之一；支持 1M token 上下文窗口（亦有来源称 256K）和 131K 输出上限。',NULL,NULL,NULL,NULL,NULL,3,1,'["x"]','参数规模（750B vs 744B MoE）和上下文窗口（1M vs 256K）在不同来源间存在差异——sc-6c703319eb56 给出最精确的 744B/40B MoE 架构描述但称 256K 窗口，而 sc-39a1a72fd163 和 sc-d4224cf9f130 均称 1M；可能源于不同评测配置或发布时间差，非根本性矛盾','["src-39a1a72fd163", "src-6c703319eb56", "src-d4224cf9f130"]','cred-e191d3f17d34','["sc-39a1a72fd163", "sc-6c703319eb56", "sc-d4224cf9f130"]',NULL,'active',NULL,NULL,NULL,'2026-07-06 13:50:17','2026-07-06 13:50:17','condense-aggregate',NULL);
INSERT INTO "l2_finding" VALUES('sf-1094ee77ffd9','_unfileted','fact','GLM-5.2 可通过 REAP 量化方案（自定义 llama.cpp 分支，约 3.6 bpw）在本地硬件上运行，实测约 13 decode tok/s，借助 DSA 技术支持约 100K 上下文窗口的可用长上下文预填充。',NULL,NULL,NULL,NULL,NULL,1,1,'["x"]',NULL,'["src-762619a5e098"]','cred-eab82627b3b8','["sc-762619a5e098"]',NULL,'active',NULL,NULL,NULL,'2026-07-06 13:50:17','2026-07-06 13:50:17','condense-aggregate',NULL);
