INSERT INTO "l3_claim" VALUES('sc-5143c8a8edfd',NULL,'TRAE Work 同时支持预置模型与自定义模型；预置模型按 Work/Code 两套模式划分（Work 含 TRAE Auto Model、Doubao-Seed-2.1-Pro/Turbo、MiniMax-M3/M2.7、GLM-5.2/5-Turbo/5、DeepSeek-V4-Pro/Flash、Kimi-K2.7-Code/K2.6；Code 模式另加 GLM-5.1、GLM-5V-Turbo、Qwen3.7/3.6-Plus），但预置模型（含 GLM-5.2）的上下文窗口大小在官方文档中未公开——仅自定义模型允许用户手动配置输入/输出 Token 上限，预置配额由 TRAE Work 内部管理且不对用户暴露；自定义模型为桌面端本地环境专属。','fact','article','src-5143c8a8edfd','["src-5143c8a8edfd"]','预置模型的上下文窗口大小在官方文档中未明确说明/未公开；仅「添加自定义模型」时允许用户手动配置「上下文窗口-输入」和「上下文窗口-输出」','19e4b778919c6fbd2e1732bbf7e0448498c30725aec2496c28d63f8e5aff8afc','对 coding/work 产品配额研究而言，最有价值的信号是「预置模型上下文窗口不透明」——用户无法从文档直接比较 GLM-5.2 等预置模型的有效上下文配额，需以实测或计费行为推断；模型阵容清单为辅证。','{"independence": "第一方官方文档，权威描述自身产品行为", "quality_density": "高：具名模型清单 + 明确的配置项与平台限制（桌面端/本地专属）", "recency": "现行产品文档，截至抓取时有效"}',NULL,'cred-9fc3c3f5b7f7',NULL,NULL,'active',NULL,NULL,NULL,'2026-07-06 13:17:14','2026-07-06 13:49:05','condense-distill',NULL);
INSERT INTO "l3_claim" VALUES('sc-9e1192eb5de0',NULL,'TRAE Work（仅 SOLO Agent）为每个对话维护独立的上下文窗口，当累积上下文超过平台允许的上限时自动触发（亦可手动触发）上下文压缩，通过移除冗余、保留关键内容以维持输出质量——而非抛错报错；开启新会话则清空先前上下文。','fact','article','src-9e1192eb5de0','["src-9e1192eb5de0"]','使用限制：仅适用于SOLO Agent（即TRAE Work）……当使用的上下文超过允许的上下文窗口时，系统自动触发一次上下文压缩……通过压缩移除冗余信息仅保留关键内容，确保AI聚焦核心上下文并维持输出质量。','5c6989a24555f530cd50edb30c6adfaefecab6977afb441cc8ff314eb98871fd','文档未说明该「允许的上下文窗口」是否等于模型原生上下文（如 GLM-5.2 的 1M）；compaction 机制的存在表明平台对上下文做了上限管理，可能未暴露模型原生完整窗口——此点为研究者推断，非文档直接陈述，需其它来源印证。','{"independence": "厂商官方文档，单一一手来源；对自家产品机制描述具权威性，但非多源独立印证", "quality_density": "描述具体机制（触发条件/行为/适用范围/UI 反馈），信息密度高、可证伪", "recency": "现行官方文档，信息时效有效"}',NULL,'cred-d4449766a3cb',NULL,NULL,'active',NULL,NULL,NULL,'2026-07-06 13:17:14','2026-07-06 13:49:05','condense-distill',NULL);
INSERT INTO "l3_claim" VALUES('sc-ecf96379cac9',NULL,'智谱于2026年6月13日向GLM Coding Plan全量用户(Lite/Pro/Max/团队版)开放GLM-5.2——其迄今最强开源模型(MIT协议):支持真正可用的1M上下文、400-500K下指令遵循接近Claude、幻觉极低、长程任务领先;实测在10万行代码项目排查中结果与Claude Opus 4.8几乎一致但慢2倍多(21分钟 vs 6分钟),作者判定为算力基建差距而非模型能力差距;最大短板是不支持多模态,Coding Plan仍限额需每天抢,反映国产infra/算力差距。','analysis','article','src-ecf96379cac9','["src-ecf96379cac9"]','稳但慢——在10万行代码项目中排查监控故障全程21分钟（Claude Opus 4.8 fast模式6分钟），过程结果几乎一样但速度差2倍多，这是算力基建差距而非模型能力差距。','945818fc55f83b5ed0f9330db78ecdd6fcb07aeeecf0bf2641b9450bc354be64','原文混合三类内容:(1)官方发布事实(日期、版本、MIT开源、1M上下文);(2)作者一手实测(10万行代码排查的21分钟 vs 6分钟计时对比)——这是本文相对通稿的增量证据;(3)解读性判断(''算力基建差距而非模型能力差距''、''Coding Plan限额反映infra差距'')。可信度主要依赖第(2)类一手数据,官方benchmark数字未经独立复测。','{"independence": "单一来源(头条号''观察者'');发布事实与benchmark数字追溯至智谱官方公告,仅计时机比为作者一手;无第二独立来源印证。", "quality_density": "高:具体可证伪数字(1M/400-500K上下文、21分钟vs6分钟、10万行代码、MIT协议、2026-06-13发布日),非空泛口号。", "recency": "2026-06-13发布,距今约3周,快变主题(AI模型)下仍有效;API''下周上线''为预测性陈述需后续校验。"}',NULL,'cred-b1f57f49fcde',NULL,NULL,'active',NULL,NULL,NULL,'2026-07-06 13:17:14','2026-07-06 13:49:05','condense-distill',NULL);
INSERT INTO "l3_claim" VALUES('sc-37f4e8b87ccc',NULL,'TRAE 国际版即将升级计费方案，可能涉及上下文配额调整','fact','post','src-37f4e8b87ccc','["src-37f4e8b87ccc"]','TRAE官方账号发布国际版计费方案升级公告','745c457e7eacd722ecfac5908cb098046876a8fc59f3eaae689568e9158f2d98','原文正文因风控墙未能抓取，主张仅基于标题和互动数据推断。TRAE 官方账号发布，为一手信源。计费方案升级的具体细节（价格、生效时间、配额变化幅度）因正文缺失而未知，属于信息不完整的主张，需后续补采原文后再迭代。','{"independence": "一手官方信源，非转发，独立性强", "quality_density": "标题明确但缺乏正文细节，信息密度中等偏低", "recency": "帖子有活跃互动（赞178/评148），应为近期发布，时效性好"}',NULL,'cred-02ab9ab2f85c',NULL,NULL,'active',NULL,NULL,NULL,'2026-07-06 13:49:05','2026-07-06 13:49:05','condense-distill',NULL);
INSERT INTO "l3_claim" VALUES('sc-39a1a72fd163',NULL,'智谱 AI 开源模型 GLM-5.2（750B 参数、1M token 上下文窗口）在关键 agentic benchmark 上表现接近 Anthropic 最强模型（差距约 1%），成本仅约五分之一。','fact','post','src-39a1a72fd163','["src-39a1a72fd163"]','A Chinese open-source model is now landing within roughly 1% of Anthropic''s best on a key agentic benchmark — at about one-fifth the cost.','b48c9f17b97aa22f043a6c53650fe0bd4c98f6e1fd8930ee93abd74ddff40d3d','原文未指明具体 benchmark 名称或评测方法论，仅引述一个模糊的 agentic benchmark 对比结果。参数规模和上下文窗口有具体数值，但核心性能声明缺乏可验证细节。来源为单条 X 推文，可能带有推广性质。','{"independence": "单一 X 推文来源，未引用评测报告或第三方验证链接；无法确认是否存在独立评测", "quality_density": "有具体数字（750B 参数、1M token 上下文、~1% 性能差距、~1/5 成本）但核心 benchmark 未具名，缺少可复现信息", "recency": "模型发布类信息时效性要求高；该推文引用的是近期发布，但 AI 领域变化极快，需持续跟踪"}',NULL,'cred-fb89cf3f83a0',NULL,NULL,'active',NULL,NULL,NULL,'2026-07-06 13:49:05','2026-07-06 13:49:05','condense-distill',NULL);
INSERT INTO "l3_claim" VALUES('sc-6c703319eb56',NULL,'智谱AI的GLM-5.2模型采用744B总参数/40B每token激活的MoE架构，支持256K上下文窗口和131K输出上限，在多项编程基准上超越Claude Opus 4.8，以MIT许可证开放权重，缩小了开源与闭源模型的差距。','fact','post','src-6c703319eb56','["src-6c703319eb56"]','744B total params (40B active per token MoE). 256K context window, 131K output cap. Ranks #1 among open models. Beats Claude Opus 4.8 in multiple coding benchmarks. MIT licensed, free weights.','c31e687f8758c39eda53a4b304f55ed0d7090b2ec25d23ec7322ea262f353a9e','该帖聚合披露了GLM-5.2的关键规格和性能声明，属二手信息汇总而非一手发布。参数规模、基准对比等具体数字可被验证或证伪，但发帖者非官方来源，需交叉印证。','{"independence": "单一来源，非官方发布，信息可能来自二手转述", "quality_density": "高密度具体数字（744B/40B/256K/131K），可证伪性强", "recency": "时效性高，涉及最新模型发布信息"}',NULL,'cred-fe58b15c2fcc',NULL,NULL,'active',NULL,NULL,NULL,'2026-07-06 13:49:05','2026-07-06 13:49:05','condense-distill',NULL);
INSERT INTO "l3_claim" VALUES('sc-762619a5e098',NULL,'GLM 5.2 REAP 模型经自定义 llama.cpp 分支量化为约3.6 bpw后，可在本地硬件上以约13 decode tok/s速度运行并支持约100k上下文窗口（通过DSA实现可用长上下文预填充）。','fact','post','src-762619a5e098','["src-762619a5e098"]','a custom ~3.6 bpw quant of GLM 5.2 REAP running at 13 decode tok/s with very usable long-context prefill (via DSA) and ~100k context window on just [本地硬件]','c5c866d49be0f27f89aa823098d4afe6a1e7ff9097d801c3a8755fbf2938783e','作者声称通过自制 ik-llama-cpp 分支与 DSA（Dynamic Sparse Attention）技术在本地硬件上实现 GLM 5.2 的长上下文推理。属个人实操报告，有具体量化参数（3.6 bpw、13 tok/s、~100k context）增强可信度，但缺乏独立复现验证。','{"independence": "单源个人推文，无独立交叉验证", "quality_density": "信息密度高：含量化精度(3.6 bpw)、推理速度(13 tok/s)、上下文长度(~100k)、技术手段(DSA)，均可复现验证", "recency": "推文时效性强，模型版本 GLM 5.2 为最新发布，信息当前有效"}',NULL,'cred-8b64582c1960',NULL,NULL,'active',NULL,NULL,NULL,'2026-07-06 13:49:05','2026-07-06 13:49:05','condense-distill',NULL);
